/* ==UserStyle==
@name         Pinterest Blue Clean
@namespace    stylish
@version      1.0
@description  Pinterest azul clean
@match        *://www.pinterest.com/*
==/UserStyle== */

/* Fondo blanco */
body {
    background: #ffffff !important;
}

/* Barra izquierda */
[data-test-id="left-nav"],
nav {
    background: #3f6fd9 !important;
}

/* Barra superior */
header {
    background: #3f6fd9 !important;
}

/* Buscador */
input {
    background: white !important;
    color: #3f6fd9 !important;
    border-radius: 25px !important;
}

/* Texto buscador */
input::placeholder {
    color: #7b96e6 !important;
}

/* Iconos barra lateral */
nav svg,
nav span,
nav a {
    color: white !important;
    fill: white !important;
}

/* Botones */
button {
    background: #3f6fd9 !important;
    color: white !important;
    border: none !important;
    border-radius: 24px !important;
}

/* Hover */
button:hover {
    background: #345fc0 !important;
}

/* Links */
a {
    color: #3f6fd9 !important;
}

/* Tarjetas normales */
article,
section {
    background: white !important;
}
